#include "fullstack_gpu.h"
#include "fullstack_core.h"
#include <assert.h>
int main(void){FS_GpuContextDesc gd=FS_GPU_CONTEXT_DESC_INIT;FS_GpuContext*g=NULL;FS_Error e=FS_ERROR_INIT;assert(fs_gpu_context_create(&gd,&g,&e)==FS_RESULT_OK);FS_Core*c=fs_core_create(fs_gpu_device(g),fs_gpu_queue(g),WGPUTextureFormat_RGBA8Unorm,64,64);assert(c);fs_core_begin_commands(c);assert(fs_cmd_rect(c,0,0,64,64,0,0xff0000ffu));WGPUCommandEncoder encoder=wgpuDeviceCreateCommandEncoder(fs_gpu_device(g),&(WGPUCommandEncoderDescriptor){0});assert(encoder);FS_CoreSceneOutput scene={0};assert(fs_core_encode_scene(c,encoder,0,0,0,1,&scene));assert(scene.texture&&scene.view&&scene.width==64&&scene.format==WGPUTextureFormat_RGBA8Unorm);WGPUCommandBuffer command=wgpuCommandEncoderFinish(encoder,&(WGPUCommandBufferDescriptor){0});assert(command);FS_SubmissionToken token={0};assert(fs_gpu_submit(g,1,&command,&token,&e)==FS_RESULT_OK);wgpuCommandBufferRelease(command);wgpuCommandEncoderRelease(encoder);fs_core_destroy(c);fs_gpu_context_destroy(g);return 0;}
